import { RelativeTime } from 'gt-next';
import { Card } from './widgets';
export function Page(props) {
  const {
  name, count, mode, show, items, label, value, custom,
  settings, context, locales, amount, date
} = props;
  const before = <RelativeTime title={<span>Title {name}</span>}><strong>Value {name}</strong>{show ? <i>Choice {count}</i> : null}</RelativeTime>;
  {
    const RelativeTime = Card;
    const shadow = <RelativeTime title={<span>Title {name}</span>}><strong>Value {name}</strong>{show ? <i>Choice {count}</i> : null}</RelativeTime>;
    return <main>{before}{shadow}</main>;
  }
}

